```python
def f(n):
    def factorial(x):
        """Calculate the factorial of a number."""
        if x == 0:
            return 1
        else:
            return x * factorial(x - 1)

    def sum_to_i(y):
        """Calculate the sum from 1 to i."""
        return (y * (y + 1)) // 2

    result = []
    for i in range(n):
        if i % 2 == 0:
            result.append(factorial(i+1))
        else:
            result.append(sum_to_i(i+1))

    return result
```
