def count_nums(arr):
    def sum_digits(n):
        """Helper function to calculate sum of digits"""
        if n < 0:
            return sum_digits(-1 * (n // 10)) - (n % 10)
        elif n == 0:
            return 0
        else:
            return n % 10 + sum_digits(n // 10)

    count = 0
    for num in arr:
        if sum_digits(num) > 0:
            count += 1

    return count
```
