def histogram(test):
    # Create an empty dictionary to store letter counts.
    count_dict = {}

    # Split the string into a list of words.
    word_list = test.split()

    for word in word_list:
        if word not in count_dict:
            count_dict[word] = 1  # If letter is not in dictionary, add it with count 1.
        else:
            count_dict[word] += 1  # If letter is already in dictionary, increment the count by 1.

    max_count = max(count_dict.values()) if count_dict else 0  # Find maximum occurrence of a letter.

    return {k: v for k, v in count_dict.items() if v == max_count}  # Return dictionary with letters having the most repetition and their counts.
```

