        open2, close2 = close2, open2

    balance = 0

    for ch in open1+open2:
        if ch == '(':
            balance += 1
        else:
            balance -= 1

            if balance < 0:
                return "No"

    balance = 0

    for ch in close1[::-1] + close2[::-1]:
        if ch == ')':
            balance += 1
        else:
            balance -= 1

            if balance < 0:
                return "No"

    return "Yes"
