```python
def prime_fib(n: int):
    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        elif num == 2 or num == 3:
            return True
        elif num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while (i * i <= num):
            if (num % i == 0 or num % (i + 2) == 0):
                return False
            i += 6
        return True

    def fib(n: int) -> int:
        a, b = 0, 1
        for _ in range(n):
            a, b = b, a + b
        return a

    count = 0
    i = 1
    while count < n:
        if is_prime(fib(i)):
            count += 1
        i += 1
    return fib(i-1)
```
